import os
import json
from stages.recovery import recover_ledgers

def replay_dead_letters(recovered_dir, dlq_dir, config):
    all_records = {}
    for f in os.listdir(recovered_dir):
        if f.startswith("recovered_") and f.endswith(".json"):
            scanner_id = f[10:-5]
            with open(os.path.join(recovered_dir, f), "r") as r:
                all_records[scanner_id] = {rec["transaction_id"]: rec for rec in json.load(r)}

    dlq_records = recover_ledgers(dlq_dir, dlq_dir, config)

    audit = {"integrated_dlq_records": 0, "discarded_duplicates": 0}

    for scanner_id, records in dlq_records.items():
        if scanner_id not in all_records:
            all_records[scanner_id] = {}

        for rec in records:
            tid = rec["transaction_id"]
            if tid in all_records[scanner_id]:
                existing = all_records[scanner_id][tid]
                drift = abs(rec["timestamp"] - existing["timestamp"])
                if drift > config["lock_timeout_sec"]:
                    all_records[scanner_id][tid] = rec
                    audit["integrated_dlq_records"] += 1
                else:
                    audit["discarded_duplicates"] += 1
            else:
                all_records[scanner_id][tid] = rec
                audit["integrated_dlq_records"] += 1

    flat_records = []
    for scanner_id in all_records:
        flat_records.extend(all_records[scanner_id].values())

    return flat_records, audit
EOF
